from pysat.solvers import Glucose3
import itertools

solver = Glucose3()

# Variables for edges: 1 to 36
def edge_var(u, v):
    if u > v:
        u, v = v, u
    # u: 0 to 7, v: u+1 to 8
    # index = u * 8 - u*(u+1)//2 + v - u - 1 + 1
    idx = u * 8 - u * (u + 1) // 2 + v - u
    return idx

# 1. Max independent set <= 4
# For every subset of 5 vertices, at least one edge exists
for subset in itertools.combinations(range(9), 5):
    clause = []
    for u, v in itertools.combinations(subset, 2):
        clause.append(edge_var(u, v))
    solver.add_clause(clause)

# 2. Vertex connectivity >= 4
# For every disjoint A, B with |A| + |B| == 6, at least one edge between A and B
vertices = set(range(9))
for subset6 in itertools.combinations(range(9), 6):
    subset6 = set(subset6)
    # partitions of subset6 into A and B
    # sizes of A can be 1, 2, 3
    for sizeA in [1, 2, 3]:
        for A in itertools.combinations(subset6, sizeA):
            A = set(A)
            B = subset6 - A
            # to avoid duplicate partitions when sizeA == 3
            if sizeA == 3 and min(A) > min(B):
                continue
            clause = []
            for u in A:
                for v in B:
                    clause.append(edge_var(u, v))
            solver.add_clause(clause)

if solver.solve():
    model = solver.get_model()
    edges = []
    for u in range(9):
        for v in range(u+1, 9):
            if model[edge_var(u, v) - 1] > 0:
                edges.append((u, v))
    print("SAT")
    print(edges)
else:
    print("UNSAT")
